import { test, expect } from '@playwright/test';
import path from 'path';
import { openAddCandidate, fillStep1, searchMyCandidates, stamp, uniquePhone } from './helpers';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

const ts = stamp();
const FIRST = 'QA-AUTO 7818c8 fin';

test.describe('«הוספת מועמד» — save only on «סיום» (#7818c8)', () => {
  test.afterAll(() => {
    console.warn(`[test-data] created candidate «${FIRST} ${ts}» (hunter_plus) — the UI has no delete; clean up manually`);
  });

  test('Candidate is created only on «סיום» and exactly once @desktop @data #7818c8', async ({ page }) => {
    // 1. Step 1 (no profile-type choice since #daf026; unique phone) → «המשך»
    const dialog = await openAddCandidate(page);
    await fillStep1(dialog, {
      first: FIRST, last: ts, phone: uniquePhone(),
      about: 'QA-AUTO מועמד לבדיקה', field: 'שיווק, מכירות ופיתוח עסקי',
    });
    const finish = dialog.getByRole('button', { name: 'סיום', exact: true });
    await expect(finish).toBeVisible();
    await expect(dialog.getByRole('textbox', { name: 'כותרת' })).not.toHaveValue('', { timeout: 60_000 });

    // Not saved yet on step 2
    const p2 = await page.context().newPage();
    await expect((await searchMyCandidates(p2, ts)).filter({ hasText: `${FIRST} ${ts}` })).toHaveCount(0);
    await p2.close();

    // 2. «סיום»
    await finish.click();
    await expect(dialog).toBeHidden({ timeout: 30_000 });

    // 3. «המועמדים שלי» — exactly one card
    const headings = await searchMyCandidates(page, ts);
    await expect(headings.filter({ hasText: `${FIRST} ${ts}` })).toHaveCount(1);
  });
});
